import re
content = open('doc/molecule.md').read()
lines = content.split('\n')
molecules = {}
for i, line in enumerate(lines):
    m = re.search(r'(TR\d{3})', line)
    if m:
        mid = m.group(1)
        ll = line.lower()
        if 'carcinogenic' in ll and 'non' not in ll:
            molecules[mid] = 'carcinogenic'
        elif 'non-carcinogenic' in ll or 'non carcinogenic' in ll:
            molecules[mid] = 'non-carcinogenic'
        elif 'inconclusive' in ll:
            molecules[mid] = 'inconclusive'
        elif 'benign' in ll or 'negative' in ll:
            molecules[mid] = 'non-carcinogenic'
        else:
            molecules[mid] = 'unknown'
print(f'Total: {len(molecules)}')
print('Carcinogenic count:', sum(1 for v in molecules.values() if v == 'carcinogenic'))
print('Non-carcinogenic:', sum(1 for v in molecules.values() if v == 'non-carcinogenic'))
print('Inconclusive:', sum(1 for v in molecules.values() if v == 'inconclusive'))
print('Sample:', dict(list(molecules.items())[:5]))

